import type {
  GPUClassBreaksMethod,
  GPUClassBreaksSettings
} from '../../../src/gpu-dataframe/column-classification/class-breaks-parameters';
import fixture from '../../oracles/fixtures/dataframe-class-breaks.json';

/**
 * mapclassify and jenkspy class breaks, generated by `test/oracles/dataframe-class-breaks.py`
 * (package versions and per-case tolerances are in the JSON). Consumed by the CPU oracle node spec
 * and the GPU spec, so both are pinned to the same reference values.
 */
export type ClassBreaksReferenceCase = {
  method: GPUClassBreaksMethod;
  /** Classes produced by the reference (for head-tail: the data-dependent count). */
  classCount: number;
  /** Reference inner edges `e[1..k-1]`. */
  innerEdges: number[];
  /** Derived absolute tolerance of every inner edge (see the generator docstring). */
  absoluteTolerance: number;
  standardDeviationInterval?: number;
  headTailRatio?: number;
  /** Class count requested from GPUClassBreaks (head-tail: an upper bound). */
  requestedClassCount?: number;
  boxPlotHinge?: number;
};

/**
 * Exact Fisher-Jenks reference of one scene and class count (an f64 dynamic program with a unique
 * optimum, agreeing with jenkspy; mapclassify agrees except where `mapclassifyAgrees` is false).
 */
export type NaturalBreaksReference = {
  classCount: number;
  /** `[min, b1, ..., max]` with classes upper-inclusive: `b[i]` is the largest value of class i. */
  exactBreaks: number[];
  /**
   * `e[1..k-1]`: the smallest value of every class after the first, which is the smallest data
   * value above `b[i-1]`. GPUClassBreaks edges are lower edges, so these are its exact answer.
   */
  exactLowerEdges: number[];
  exactClassSizes: number[];
  exactGoodnessOfVarianceFit: number;
  jenkspyAgrees: boolean;
  mapclassifyAgrees: boolean;
  /** `e[1..k-1]` of the mapclassify partition, which is marginally suboptimal where it disagrees. */
  mapclassifyLowerEdges: number[];
};

/** One reference column. */
export type ClassBreaksReferenceScene = {
  values: number[];
  cases: ClassBreaksReferenceCase[];
  naturalBreaks: NaturalBreaksReference[];
  /** Adversarial scenes: the sorted distinct values after the first (one class per value). */
  distinctValueEdges?: number[];
};

/** The whole fixture. */
export type ClassBreaksReferenceFixture = {
  versions: Record<string, string>;
  generator: string;
  scenes: Record<string, ClassBreaksReferenceScene>;
};

/** The parsed fixture. */
export const CLASS_BREAKS_REFERENCE = fixture as ClassBreaksReferenceFixture;

/**
 * Natural-breaks cases in which GPUClassBreaks stops in a neighbouring local optimum of the
 * coordinate descent instead of the exact Fisher-Jenks partition. Exhaustive single-cut checks
 * prove both are local minima; their exact total SSD excesses are 0.000109457337 and
 * 0.013883616632. The fit tolerance below applies only to these fixtures, not arbitrary data.
 * The first is also the
 * partition mapclassify 2.11 returns, which is not optimal either. Keyed by `scene k`.
 */
export const NATURAL_BREAKS_LOCAL_OPTIMA: Readonly<Record<string, 'mapclassify' | 'neighbouring'>> =
  {
    'lognormal 7': 'mapclassify',
    'outlier-pair 5': 'neighbouring'
  };

/** Largest goodness of variance fit shortfall of a neighbouring local optimum. */
export const NATURAL_BREAKS_LOCAL_OPTIMUM_FIT_TOLERANCE = 2e-6;

/** GPUClassBreaks per-frame parameters reproducing one reference case. */
export function getReferenceParameters(
  referenceCase: ClassBreaksReferenceCase
): GPUClassBreaksSettings {
  return {
    method: referenceCase.method,
    classCount: referenceCase.requestedClassCount ?? referenceCase.classCount,
    standardDeviationInterval: referenceCase.standardDeviationInterval,
    headTailRatio: referenceCase.headTailRatio,
    boxPlotHinge: referenceCase.boxPlotHinge
  };
}

/**
 * Returns a description of every inner edge outside its tolerance, or an empty list. `breaks` is
 * the `e[0..k]` output, `classCount` the produced count.
 */
export function getReferenceEdgeMismatches(
  label: string,
  breaks: ArrayLike<number>,
  classCount: number,
  referenceCase: ClassBreaksReferenceCase
): string[] {
  const mismatches: string[] = [];
  if (classCount !== referenceCase.classCount) {
    mismatches.push(`${label}: classCount ${classCount} != ${referenceCase.classCount}`);
    return mismatches;
  }
  for (const [index, expected] of referenceCase.innerEdges.entries()) {
    const actual = breaks[index + 1];
    if (!(Math.abs(actual - expected) <= referenceCase.absoluteTolerance)) {
      mismatches.push(
        `${label}: e[${index + 1}] ${actual} != ${expected} (tolerance ${referenceCase.absoluteTolerance})`
      );
    }
  }
  return mismatches;
}

/**
 * Goodness of variance fit `1 - SDCM / SDAM` in f64 of the classes cut by inner edges, with the
 * GPUClassBreaks class rule (a value at or above edge `e[i]` is in class `i` or later).
 */
export function getGoodnessOfVarianceFit(
  values: ArrayLike<number>,
  innerEdges: readonly number[]
): number {
  const finite = Array.from(values).filter(Number.isFinite);
  const mean = finite.reduce((sum, value) => sum + value, 0) / finite.length;
  const total = finite.reduce((sum, value) => sum + (value - mean) ** 2, 0);
  const classes: number[][] = innerEdges.map(() => []);
  classes.push([]);
  for (const value of finite) {
    let index = 0;
    while (index < innerEdges.length && value >= innerEdges[index]) {
      index++;
    }
    classes[index].push(value);
  }
  let within = 0;
  for (const members of classes) {
    if (members.length) {
      const classMean = members.reduce((sum, value) => sum + value, 0) / members.length;
      within += members.reduce((sum, value) => sum + (value - classMean) ** 2, 0);
    }
  }
  return 1 - within / total;
}

/** Class sizes with the GPUClassBreaks class rule. */
export function getClassSizes(values: ArrayLike<number>, innerEdges: readonly number[]): number[] {
  const sizes = new Array<number>(innerEdges.length + 1).fill(0);
  for (const value of Array.from(values)) {
    let index = 0;
    while (index < innerEdges.length && value >= innerEdges[index]) {
      index++;
    }
    sizes[index]++;
  }
  return sizes;
}
